package game.agent.eval;
import game.agent.llm.Json;import java.util.*;
/** Wilson score intervals describe observed completion samples, not model guarantees. */
public final class EvaluationStatistics {
 private EvaluationStatistics(){}
 public static List<Object> compare(List<Map<String,Object>> rows){Map<String,List<Map<String,Object>>> groups=new LinkedHashMap<>();for(Map<String,Object> row:rows)groups.computeIfAbsent((String)row.get("model"),k->new ArrayList<>()).add(row);List<Object> result=new ArrayList<>();for(Map.Entry<String,List<Map<String,Object>>> entry:groups.entrySet()){int finished=0,completed=0,faults=0,recovered=0,battles=0,wins=0,draws=0;long steps=0,invalid=0,tokens=0;boolean usage=true,priced=true;double cost=0,latency=0;int calls=0;for(Map<String,Object> row:entry.getValue()){if(Arrays.asList("RUNNING","PAUSED","QUEUED").contains(row.get("status")))continue;finished++;if(Boolean.TRUE.equals(row.get("completed")))completed++;Map<String,Object> m=Json.asObject(row.get("metrics"));if(m.containsKey("battleResult")){battles++;wins+=n(m,"battleWin");draws+=n(m,"battleDraw");}steps+=n(m,"actionSteps");invalid+=n(m,"invalidActions");faults+=n(m,"injectedFaults");recovered+=n(m,"recoveredFaults");if(m.get("totalTokens")==null)usage=false;else tokens+=n(m,"totalTokens");if(m.get("cost")==null)priced=false;else cost+=((Number)m.get("cost")).doubleValue();int sample=(int)n(m,"providerCalls");if(m.get("averageProviderLatencyMs")!=null)latency+=((Number)m.get("averageProviderLatencyMs")).doubleValue()*sample;calls+=sample;}
  result.add(Json.object("battleCases",battles,"battleWins",wins,"battleDraws",draws,"battleWinRate",battles==0?null:wins/(double)battles,"battleWin95Wilson",wilson(wins,battles),"model",entry.getKey(),"planned",entry.getValue().size(),"finished",finished,"completed",completed,"completionRate",finished==0?null:completed/(double)finished,"completion95Wilson",wilson(completed,finished),"averageActionSteps",finished==0?null:steps/(double)finished,"invalidActionRate",steps==0?null:invalid/(double)steps,"averageProviderLatencyMs",calls==0?null:latency/calls,"totalTokens",finished==0||!usage?null:tokens,"cost",finished==0||!priced?null:cost,"injectedFaults",faults,"recoveredFaults",recovered,"recoverySuccessRate",faults==0?null:recovered/(double)faults));}return result;}
 public static List<Double> wilson(int success,int count){if(success<0||success>count)throw new IllegalArgumentException("INVALID_SAMPLE");if(count==0)return Collections.emptyList();double z=1.95996398454,p=success/(double)count,d=1+z*z/count,center=(p+z*z/(2*count))/d,margin=z*Math.sqrt(p*(1-p)/count+z*z/(4.0*count*count))/d;return Arrays.asList(Math.max(0,center-margin),Math.min(1,center+margin));}
 private static long n(Map<String,Object> m,String k){return m.get(k)==null?0:EvaluationRandom.number(m.get(k));}
}
